"""Tests for the task shape feature extractor exposed as ``subject``."""

from subject import (
    EnumFileType,
    ModelTaskShapeContext,
    ModelTaskShapeFeatures,
    extract_task_shape,
)


def test_none_context_returns_default_features():
    features = extract_task_shape(None)
    assert isinstance(features, ModelTaskShapeFeatures)
    assert features.diff_size == 0
    assert features.file_types == frozenset()
    assert features.novelty_score == 0.5


def test_none_context_equals_fully_default_features():
    assert extract_task_shape(None) == ModelTaskShapeFeatures()


def test_empty_context_returns_default_features():
    features = extract_task_shape(ModelTaskShapeContext())
    assert features.diff_size == 0
    assert features.file_types == frozenset()
    assert features.novelty_score == 0.5


def test_diff_size_sums_added_and_removed():
    features = extract_task_shape(
        ModelTaskShapeContext(diff_lines_added=120, diff_lines_removed=30)
    )
    assert features.diff_size == 150


def test_diff_size_with_only_added():
    features = extract_task_shape(ModelTaskShapeContext(diff_lines_added=7))
    assert features.diff_size == 7


def test_diff_size_with_only_removed():
    features = extract_task_shape(ModelTaskShapeContext(diff_lines_removed=9))
    assert features.diff_size == 9


def test_diff_size_with_zero_added_counts_removed():
    features = extract_task_shape(
        ModelTaskShapeContext(diff_lines_added=0, diff_lines_removed=5)
    )
    assert features.diff_size == 5


def test_novelty_score_is_passed_through():
    features = extract_task_shape(
        ModelTaskShapeContext(ledger_novelty_score=0.85)
    )
    assert features.novelty_score == 0.85


def test_novelty_score_of_zero_is_preserved():
    features = extract_task_shape(
        ModelTaskShapeContext(ledger_novelty_score=0.0)
    )
    assert features.novelty_score == 0.0


def test_novelty_score_of_one_is_preserved():
    features = extract_task_shape(
        ModelTaskShapeContext(ledger_novelty_score=1.0)
    )
    assert features.novelty_score == 1.0


def test_novelty_score_defaults_when_absent():
    features = extract_task_shape(ModelTaskShapeContext(diff_lines_added=10))
    assert features.novelty_score == 0.5


def test_python_extension_is_classified():
    features = extract_task_shape(ModelTaskShapeContext(file_paths=("main.py",)))
    assert features.file_types == frozenset({EnumFileType.PYTHON})


def test_typescript_extensions_share_one_type():
    features = extract_task_shape(
        ModelTaskShapeContext(file_paths=("app.ts", "component.tsx"))
    )
    assert features.file_types == frozenset({EnumFileType.TYPESCRIPT})


def test_yaml_and_markdown_extensions_are_classified():
    features = extract_task_shape(
        ModelTaskShapeContext(file_paths=("config.yaml", "pipeline.yml", "README.md"))
    )
    assert features.file_types == frozenset(
        {EnumFileType.YAML, EnumFileType.MARKDOWN}
    )


def test_unknown_and_missing_extensions_are_other():
    features = extract_task_shape(
        ModelTaskShapeContext(file_paths=("data.json", "Makefile"))
    )
    assert features.file_types == frozenset({EnumFileType.OTHER})


def test_extension_matching_is_case_insensitive():
    features = extract_task_shape(
        ModelTaskShapeContext(file_paths=("Main.PY", "Notes.Md", "Setup.YAML"))
    )
    assert features.file_types == frozenset(
        {EnumFileType.PYTHON, EnumFileType.MARKDOWN, EnumFileType.YAML}
    )


def test_extension_is_taken_after_the_last_dot():
    features = extract_task_shape(
        ModelTaskShapeContext(
            file_paths=("backup.tar.py", "src/pkg.d/module.py")
        )
    )
    assert features.file_types == frozenset({EnumFileType.PYTHON})


def test_duplicate_file_types_collapse_into_a_distinct_set():
    features = extract_task_shape(
        ModelTaskShapeContext(
            file_paths=("a.py", "b.ts", "c.py", "notes.txt")
        )
    )
    assert features.file_types == frozenset(
        {EnumFileType.PYTHON, EnumFileType.TYPESCRIPT, EnumFileType.OTHER}
    )


def test_all_fields_are_extracted_together():
    context = ModelTaskShapeContext(
        diff_lines_added=45,
        diff_lines_removed=5,
        file_paths=("service.py", "schema.yaml"),
        ledger_novelty_score=0.9,
    )
    features = extract_task_shape(context)
    assert features == ModelTaskShapeFeatures(
        diff_size=50,
        file_types=frozenset({EnumFileType.PYTHON, EnumFileType.YAML}),
        novelty_score=0.9,
    )


def test_novelty_only_context_keeps_other_defaults():
    features = extract_task_shape(
        ModelTaskShapeContext(ledger_novelty_score=1.0)
    )
    assert features.diff_size == 0
    assert features.file_types == frozenset()
    assert features.novelty_score == 1.0
